function escapeHtml(str) {
  return String(str ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

export function getCrossItem(appId, level) {
  const list = CROSS_LEVEL_DATA[appId];
  if (!list || !list.length) return null;
  const clamped = Math.max(0, Math.min(list.length - 1, Number(level) || 0));
  return list[clamped] || list[0];
}

export function renderCrossLevelSectionHtml(level, activeName = '', lang = 'ko', currentApp = 'occupation', maxLevel = 999) {
  const lv = Math.max(0, Math.min(maxLevel, Number(level) || 0));
  const prevLv = lv > 0 ? lv - 1 : maxLevel;
  const nextLv = lv < maxLevel ? lv + 1 : 0;
  const randLv = (lv * 173 + 317) % (maxLevel + 1);
  const cleanLang = (lang && CROSS_I18N[lang]) ? lang : 'ko';
  const dict = CROSS_I18N[cleanLang] || CROSS_I18N.en;
  const useEnData = cleanLang !== 'ko';
  const langQuery = cleanLang !== 'ko' ? `?lang=${encodeURIComponent(cleanLang)}` : '';
  const cleanName = String(activeName || '').trim();
  const encodedName = cleanName ? encodeURIComponent(cleanName) : '';

  const prevLabel = dict.prevBtn.replace('{prev}', prevLv);
  const randLabel = dict.randBtn;
  const nextLabel = dict.nextBtn.replace('{next}', nextLv);

  const siblingIds = Object.keys(CROSS_LEVEL_DATA).filter(k => k !== currentApp);
  const cardsHtml = siblingIds.map(appId => {
    const meta = CROSS_APPS_META[appId];
    const targetLv = Math.min(meta.maxLevel, lv);
    const item = getCrossItem(appId, targetLv);
    if (!item) return '';
    const padded = String(targetLv).padStart(5, '0');
    const imgUrl = `${meta.r2Prefix}/${padded}.webp`;
    const levelUrl = `${meta.origin}/level/${targetLv}${langQuery}`;
    const title = useEnData ? (item.et || item.t) : item.t;
    const era = useEnData ? (item.ey || item.y) : item.y;
    const val = useEnData ? (item.ev || item.v) : item.v;
    const feat = useEnData ? (item.ef || item.f) : item.f;
    const verdict = useEnData ? (item.ea || item.a) : item.a;

    const badgeText = (dict[`badge_${appId}`] || `Lv.${targetLv}`).replace('{lv}', targetLv);
    const lblEra = dict.lblEra;
    const lblVal = dict[`lblVal_${appId}`] || dict.lblVal_myhome;
    const lblFeat = dict[`lblFeat_${appId}`] || dict.lblFeat_myhome;
    const goLvText = (dict[`goLv_${appId}`] || `Lv.${targetLv} →`).replace('{lv}', targetLv);

    const nameBtnHtml = cleanName
      ? `<a href="${meta.origin}/name/${encodedName}${langQuery}" class="cross-name-search-btn">${escapeHtml((dict[`searchName_${appId}`] || '').replace('{name}', cleanName))}</a>`
      : '';

    return `
      <article class="cross-level-card" data-cross-app="${appId}">
        <div class="cross-card-badge">${escapeHtml(badgeText)}</div>
        <a href="${levelUrl}" class="cross-card-main-link">
          <div class="cross-card-media">
            <img src="${imgUrl}" alt="Lv.${targetLv} ${escapeHtml(title)}" loading="lazy" width="320" height="240" class="cross-card-img" onerror="this.onerror=null;this.src='data:image/svg+xml;utf8,<svg xmlns=%22http://www.w3.org/2000/svg%22 width=%22400%22 height=%22260%22 viewBox=%220 0 400 260%22><defs><linearGradient id=%22g%22 x1=%220%22 y1=%220%22 x2=%221%22 y2=%221%22><stop offset=%220%25%22 stop-color=%22%230f172a%22/><stop offset=%22100%25%22 stop-color=%22%231e3a8a%22/></linearGradient></defs><rect width=%22400%22 height=%22260%22 fill=%22url(%23g)%22/><text x=%22200%22 y=%22115%22 text-anchor=%22middle%22 font-size=%2248%22>${meta.icon}</text><text x=%22200%22 y=%22165%22 text-anchor=%22middle%22 fill=%22%2338bdf8%22 font-family=%22sans-serif%22 font-size=%2222%22 font-weight=%22bold%22>Lv.${targetLv}</text></svg>';" />
            <span class="cross-lv-pill">Lv.${targetLv}</span>
          </div>
          <div class="cross-card-body">
            <h4 class="cross-card-title">${escapeHtml(title)}</h4>
            <dl class="cross-card-specs">
              <div><dt>${escapeHtml(lblEra)}</dt><dd>${escapeHtml(era)}</dd></div>
              <div><dt>${escapeHtml(lblVal)}</dt><dd>${escapeHtml(val)}</dd></div>
              <div><dt>${escapeHtml(lblFeat)}</dt><dd>${escapeHtml(feat)}</dd></div>
            </dl>
            <p class="cross-card-verdict">“${escapeHtml(verdict)}”</p>
          </div>
        </a>
        <div class="cross-card-actions">
          <a href="${levelUrl}" class="cross-go-level-btn">${escapeHtml(goLvText)}</a>
          ${nameBtnHtml}
        </div>
      </article>
    `;
  }).join('\n');

  const foodHref = cleanName
    ? `https://food.tellmyname.app/name/${encodedName}${langQuery}`
    : `https://food.tellmyname.app/${langQuery}`;
  const foodLabel = cleanName
    ? dict.searchFood.replace('{name}', cleanName)
    : dict.exploreFood;

  return `
    <div id="cross-level-reference-root" class="cross-level-wrapper">
      <nav class="inline-step-nav-bar" aria-label="Level step navigation">
        <a href="/level/${prevLv}${langQuery}" class="step-nav-btn step-prev-btn" data-target-level="${prevLv}" data-target-level="${prevLv}" data-target-level="${prevLv}" data-step-level="${prevLv}">${escapeHtml(prevLabel)}</a>
        <a href="/level/${randLv}${langQuery}" class="step-nav-btn step-rand-btn" data-target-level="${randLv}" data-target-level="${randLv}" data-target-level="${randLv}" data-step-level="${randLv}">${escapeHtml(randLabel)}</a>
        <a href="/level/${nextLv}${langQuery}" class="step-nav-btn step-next-btn" data-target-level="${nextLv}" data-target-level="${nextLv}" data-target-level="${nextLv}" data-step-level="${nextLv}">${escapeHtml(nextLabel)}</a>
      </nav>
      <section class="cross-level-section" aria-label="Multiverse Level ${lv} Cross-Reference">
        <div class="cross-level-header">
          <span class="cross-level-eyebrow">MULTIVERSE LEVEL ${lv} CROSS-CHECK</span>
          <h3 class="cross-level-title">${escapeHtml(dict.secTitle.replace('{lv}', lv))}</h3>
          <p class="cross-level-desc">${escapeHtml(dict.secDesc.replace('{lv}', lv))}</p>
        </div>
        <div class="cross-level-grid">
          ${cardsHtml}
        </div>
        <div class="cross-food-banner">
          <a href="${foodHref}" class="cross-food-btn">${escapeHtml(foodLabel)}</a>
        </div>
      </section>
    </div>
  `;
}
